CREATE TABLE crop_locks(id BIGSERIAL PRIMARY KEY,inventory_reservation_id UUID NOT NULL UNIQUE,batch_id BIGINT NOT NULL,buyer_id BIGINT NOT NULL,quantity NUMERIC(12,2) NOT NULL,status VARCHAR(20) NOT NULL,locked_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,expired_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE orders(id BIGSERIAL PRIMARY KEY,buyer_id BIGINT NOT NULL,total_amount NUMERIC(15,2) NOT NULL DEFAULT 0,status VARCHAR(20) NOT NULL,delivery_address TEXT,order_date TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,return_state VARCHAR(30));
CREATE TABLE order_items(id BIGSERIAL PRIMARY KEY,order_id BIGINT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,batch_id BIGINT NOT NULL,farmer_id BIGINT,inventory_reservation_id UUID NOT NULL,quantity NUMERIC(12,2) NOT NULL,unit_price NUMERIC(12,2) NOT NULL,subtotal NUMERIC(15,2) NOT NULL);
CREATE TABLE order_status_history(id BIGSERIAL PRIMARY KEY,order_id BIGINT NOT NULL REFERENCES orders(id),from_status VARCHAR(20),to_status VARCHAR(20) NOT NULL,changed_by BIGINT,changed_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE idempotency_records(id BIGSERIAL PRIMARY KEY,idempotency_key VARCHAR(200) NOT NULL,command VARCHAR(100) NOT NULL,user_id BIGINT NOT NULL,request_hash VARCHAR(64) NOT NULL,response_status INTEGER,response_body TEXT,state VARCHAR(20) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(idempotency_key,command,user_id));
CREATE TABLE order_sagas(id UUID PRIMARY KEY,order_id BIGINT,saga_type VARCHAR(50) NOT NULL,state VARCHAR(30) NOT NULL,last_error TEXT,updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE outbox_events(id UUID PRIMARY KEY,aggregate_type VARCHAR(100) NOT NULL,aggregate_id VARCHAR(100) NOT NULL,event_type VARCHAR(100) NOT NULL,event_version INTEGER NOT NULL,payload JSONB NOT NULL,status VARCHAR(30) NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,created_at TIMESTAMP WITH TIME ZONE NOT NULL,published_at TIMESTAMP WITH TIME ZONE,last_error TEXT);
CREATE TABLE processed_events(event_id UUID PRIMARY KEY,processed_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_orders_buyer ON orders(buyer_id);CREATE INDEX idx_items_farmer ON order_items(farmer_id);CREATE INDEX idx_locks_buyer ON crop_locks(buyer_id,status);
